var getAllServices = async (filters) => {
  const { type, location, rating } = filters;
  const andConditions = [];
  if (type) {
    andConditions.push({
      OR: [
        { categoryId: type },
        {
          category: {
            name: { contains: type, mode: "insensitive" }
          }
        }
      ]
    });
  }
  if (location) {
    andConditions.push({
      technician: {
        OR: [
          {
            user: {
              address: { contains: location, mode: "insensitive" }
            }
          }
        ]
      }
    });
  }
  if (rating) {
    andConditions.push({
      technician: {
        rating: { gte: Number(rating) }
      }
    });
  }
  const whereConditions = andConditions.length > 0 ? { AND: andConditions } : {};
  const services = await prisma.service.findMany({
    where: whereConditions,
    include: {
      category: {
        select: {
          categoryId: true,
          name: true
        }
      },
      technician: {
        include: {
          user: {
            select: {
              name: true,
              email: true,
              phone: true,
              address: true
            }
          }
        }
      }
    }
  });
  return services;
};
