var createReview = async (customerId, payload) => {
  const { bookingId, rating, comment } = payload;
  if (!rating || rating < 1 || rating > 5) {
    throw new Error("Rating must be an integer between 1 and 5");
  }
  const booking = await prisma.booking.findUnique({
    where: { bookingId },
    include: {
      review: true,
      technician: true
    }
  });
  if (!booking) {
    throw new Error("Booking not found");
  }
  if (booking.customerId !== customerId) {
    throw new Error("Unauthorized: You can only review your own bookings");
  }
  if (booking.status !== BookingStatus.COMPLETED) {
    throw new Error(
      `You can only review a booking after it is COMPLETED (current status: ${booking.status})`
    );
  }
  if (booking.review) {
    throw new Error("You have already submitted a review for this booking");
  }
  const targetTechnicianId = booking.technician.technicianId;
  const result = await prisma.$transaction(async (tx) => {
    const newReview = await tx.review.create({
      data: {
        bookingId,
        customerId,
        technicianId: targetTechnicianId,
        rating,
        comment
      },
      include: {
        customer: {
          select: {
            userId: true,
            name: true
          }
        }
      }
    });
    const aggregate = await tx.review.aggregate({
      where: {
        technicianId: targetTechnicianId
      },
      _avg: {
        rating: true
      },
      _count: {
        reviewId: true
      }
    });
    const newAverageRating = aggregate._avg.rating ? Number(aggregate._avg.rating.toFixed(1)) : 0;
    await tx.technicianProfile.update({
      where: {
        technicianId: targetTechnicianId
      },
      data: {
        rating: newAverageRating
      }
    });
    return newReview;
  });
  return result;
};
var getReviewsForTechnician = async (technicianId) => {
  const reviews = await prisma.review.findMany({
    where: { technicianId },
    include: {
      customer: {
        select: {
          userId: true,
          name: true
        }
      }
    },
    orderBy: {
      createdAt: "desc"
    }
  });
  const totalReviews = reviews.length;
  const averageRating = totalReviews > 0 ? Number(
    (reviews.reduce((acc, curr) => acc + curr.rating, 0) / totalReviews).toFixed(1)
  ) : 0;
  return {
    technicianId,
    averageRating,
    totalReviews,
    reviews
  };
};
var reviewService = {
  createReview,
  getReviewsForTechnician
};

